// The one controls definition everything reads: the in-game How to Play, the Settings
// key list, and docs/CONTROLS.md (generated by scripts/export-controls.ts and checked
// by a test). Keyboard actions come from the key bindings (lib/keybinds), so a
// player's own bindings show wherever keys are named; touch controls are listed here
// as they are laid out in the fight's HUD (engine/scene/ContractZeroScene).

import { ACTIONS, DEFAULT_BINDS, keyLabel, type Action, type Binds } from './keybinds'

export interface ControlRow { action: string; keys: string; note?: string }

/** Notes that matter to a player, per action (what it needs, how it behaves). */
const NOTES: Partial<Record<Action, string>> = {
  fire: 'Left mouse also fires',
  aim: 'Right mouse also aims; hold by default (Settings can make it a toggle)',
  interact: 'Hold until the bar fills (Settings can make it press-once)',
  inspect: 'What you are looking at: stats, condition, what it is for',
  heal: 'Takes a moment and lowers your weapon',
  crouch: 'Hold by default (Settings can make it a toggle)',
  target: 'Snaps to the nearest visible enemy; press again to cycle',
  nvg: 'When equipped (issued for night operations)',
  light: 'When the weapon has a light',
  laser: 'When the weapon has a laser',
  optic: 'When the weapon has an optic',
  opsMenu: 'Training campaign only',
  swap: 'Also 1 / 2 to pick a slot',
}

/** Keyboard and mouse rows, grouped as the bindings are, with the player's keys. */
export function desktopControls(binds: Binds = DEFAULT_BINDS): { group: string; rows: ControlRow[] }[] {
  const groups = [...new Set(ACTIONS.map((a) => a.group))]
  const out: { group: string; rows: ControlRow[] }[] = groups.map((g) => ({
    group: g,
    rows: ACTIONS.filter((a) => a.group === g).map((a) => ({
      action: a.label,
      keys: binds[a.id].filter(Boolean).map((c) => keyLabel(c)).join(' / ') || 'unbound',
      note: NOTES[a.id],
    })),
  }))
  out.unshift({ group: 'Mouse and system', rows: [
    { action: 'Look and aim', keys: 'Mouse', note: 'Click the game to capture the mouse' },
    { action: 'Fire', keys: 'Left mouse' },
    { action: 'Aim down sights', keys: 'Right mouse' },
    { action: 'Pause, release the mouse', keys: 'Esc', note: 'Reserved: not rebindable' },
  ] })
  return out
}

